R=Path(__file__).resolve().parents[3];D=Path(__file__).resolve().parent;E=html.escape
A=[]
def p(s):return '<p>'+s+'</p>'
def h(s):return '<h2>'+s+'</h2>'
def table(c,heads,rows):return '<div class="table-wrap"><table><caption>'+c+'</caption><thead><tr>'+''.join('<th scope="col">'+v+'</th>' for v in heads)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
SBA=('SBA: write your business plan','https://www.sba.gov/business-guide/plan-your-business/write-your-business-plan')
def add(slug,title,desc,alt,sections,sources,related):
 body=p(desc)+p('<strong>Example basis:</strong> Businesses, amounts, fees and outcomes in the worked examples are fictional planning assumptions in USD, prepared November 5, 2026. They are not market averages, observed customer results or income promises.')
 toc=[]
 for i,(heading,content) in enumerate(sections,1):
  body+=f'<h2 id="section-{i}">{E(heading)}</h2>'+content;toc.append(f'<li><a href="#section-{i}">{E(heading)}</a></li>')
 body='<nav class="toc" aria-label="On this page"><strong>On this page</strong><ol>'+''.join(toc)+'</ol></nav>'+body
 body+=h('Sources and method')+p('The examples and reconciliations are original. These publisher resources provide context for planning structures and workflow definitions; their platform features or regional requirements are not automatically NexalyPlanner features.')+'<ul>'+''.join(f'<li><a href="{u}">{E(t)}</a></li>' for t,u in sources)+'</ul>'
 A.append(dict(slug=slug,title=title,desc=desc,alt=alt,body=body,sources=sources,related=related))
add('farmers-market-business-plan','Farmers Market Business Plan: Stall Costs, Waste & Cash','Plan a farmers market stall with sell-through, samples, spoilage, market-day costs and owner time. Follow a filled example and a rainy-day cash test.','Produce vendor arranging vegetable crates at a morning farmers market',[
('Define one market-day offer before a season forecast',p('A farmers market business plan should explain the buyer, offer, supply, stall process and cash needed for one market day. Start with an event you can measure. A season-wide sales target is weak evidence if you do not know how much product returns unsold or how many hours the event consumes.')+p('This fictional produce vendor prepares 120 identical boxes for one Saturday, each costing $4 and priced at $10. The customer hypothesis is that nearby households want a convenient small mixed box. The owner will compare local alternatives on contents, freshness, delivered convenience and price, then record actual purchase and refusal reasons. None of that demand is established by the example.')),
('Reconcile every prepared box',table('Illustrative 120-box event',['Disposition','Boxes','Cost basis'],[['Sold','84','$336'],['Samples','6','$24'],['Spoiled / written off','10','$40'],['Unsold, still sellable','20','$80'],['Total prepared','120','$480']])+p('Sell-through is 84 ÷ 120 = 70%, while spoilage is 10 ÷ 120 = 8.33%. Samples are neither sales nor spoiled units. The 20 sellable boxes remain inventory at the assumed $4 cost; do not erase their cost or count them as cash. If they cannot be sold later, the model needs an additional write-off.')+p('Keep counts by product when the range changes. One box-equivalent is a simplifying unit here, not permission to combine kilograms, bunches and jars into the same inventory denominator. Record what is packed, sold, sampled, damaged and brought back before planning the next batch.')),
('Price the whole event, including owner time',table('Illustrative base market day',['Line','Calculation','Amount'],[['Revenue','84 × $10','$840'],['Cost of sold boxes','84 × $4','−$336'],['Samples and waste','24 + 40','−$64'],['Market fee','Assumed event fee','−$75'],['Transport','Round-trip assumption','−$35'],['Paid helper','Entered total cost','−$60'],['Payment fees','2.5% × $840','−$21'],['Operating remainder','840 − 336 − 64 − 75 − 35 − 60 − 21','$249']])+p('The $249 excludes owner pay, tax, equipment replacement and other business overhead. If the owner values nine hours of preparation, travel, trading and cleanup at $20 per hour, a separate notional $180 allowance leaves $69. That allowance measures the economics of owner time; it is not an extra cash payment in this example. The 2.5% fee is a hypothetical assumption, not a processor quote.')+p('The <a href="https://extension.missouri.edu/publications/g648">University of Missouri break-even guide</a> provides a broader pricing framework. Use real local costs and accepted prices. A generic markup cannot prove that this stall or a second market is viable.')),
('Check committed cash and a slower event',p('Opening cash is $1,200. Buying all 120 prepared boxes uses $480; the market, transport and helper use $170. Collecting $840 and paying $21 in fees leaves $1,369: $1,200 − $480 − $170 + $840 − $21. Cash rose $169, less than the $249 operating remainder because $80 remains in stock.')+p('For this already-prepared batch, recover the $650 preparation and event cash commitment using $10 less the assumed 2.5% fee per sale: $650 ÷ $9.75 = 66.67. That means at least 67 sales to recover those listed cash outlays. It is a cash-recovery threshold for this fixed batch, not a universal accounting break-even formula or a guarantee all remaining stock will be usable.')+table('Illustrative rainy-day sensitivity',['Measure','84 sold','60 sold'],[['Revenue','$840','$600'],['Payment fees','$21','$15'],['Samples / waste','6 / 10 boxes','6 / 10 boxes'],['Sellable boxes left','20','44'],['Operating remainder before owner time','$249','$111'],['Closing cash','$1,369','$1,135']])+p('At 60 sales, preparation and event commitments remain unchanged. The $111 operating remainder coexists with a $65 cash decline because $176 is left in 44 sellable boxes. If rain also increases spoilage, reduce inventory and the operating result accordingly.')),
('Write the operating plan and review gates',p('Record supplier or harvest availability, packing time, transport, stall setup, payment handling, condition checks and the plan for remaining goods. Confirm the actual market agreement and applicable local food, labeling, permit and insurance requirements with the responsible official sources before trading. This organizational example does not determine those requirements or provide food-safety instructions.')+p('Copy these plan fields: buyer and evidence; box contents and selling unit; prepared quantity; landed cost; sale price; sample and spoilage assumptions; event costs; owner and helper hours; cash dates; weather scenario; and review owner. By the next event, compare actual counts and feedback before adding another product or market.')+p('Use the <a href="/tools/business-plan-template/">free editable business plan template</a> for the wider plan and the <a href="/tools/craft-fair-stock-reconciliation/">craft-fair stock reconciliation worksheet</a> only if its documented fields match your event. The <a href="/journal/cash-flow-forecast-template-example/">13-week cash example</a> helps connect several market dates without treating leftover stock as collected money.'))
],[SBA,('University of Missouri Extension: break-even pricing','https://extension.missouri.edu/publications/g648')],'/planners/small-business-planner-2026-2028/')
add('accounting-firm-business-plan','Accounting Firm Business Plan: Client Capacity, Fees & Cash','Build an accounting practice business plan around service scope, client hours, review capacity, fee assumptions and collections. Includes a filled monthly example.','Silver-haired accounting practice owner planning client work beside anonymous folders',[
('Choose services and a client segment you can support',p('An accounting firm business plan needs a defined service, an appropriate professional scope, a client-acquisition process and a realistic capacity model. “More clients” is not a delivery plan. Work volume depends on transaction complexity, record quality, review effort and deadlines, not only the number of engagements.')+p('This fictional founder-led practice models recurring bookkeeping support and bounded cleanup projects for small service businesses. It does not assume the owner may provide audits, regulated tax services or use a protected professional title. Verify those matters with the relevant regulator and actual qualifications before marketing services. The worked plan is operational, not professional licensing or tax guidance.')),
('Allocate hours before setting client targets',table('Illustrative monthly capacity',['Use','Hours','Treatment'],[['Total founder availability','160','Starting calendar'],['Sales and administration','32','Not client delivery'],['Quality review','16','Reserved separately'],['Training / process maintenance','8','Reserved separately'],['Client delivery capacity','104','160 − 32 − 16 − 8'],['12 recurring clients × 6 hours','72','Direct delivery estimate'],['4 cleanup projects × 5 hours','20','Direct delivery estimate'],['Unassigned delivery buffer','12','104 − 72 − 20']])+p('Quality review is outside the six-hour direct-delivery estimate in this model. If your client estimate already contains review time, change the schedule so it is not counted twice. Preserve the evidence behind each estimate: service scope, record volume, exceptions and actual time per client.')+p('Three new client onboardings at five hours each would add 15 hours, taking direct delivery from 92 to 107 hours. That exceeds the 104-hour limit by three hours and consumes the buffer before considering their future recurring work. Even two onboardings would leave only two hours spare. Stagger starts, reduce cleanup bookings or revise capacity explicitly instead of promising every inquiry an immediate start.')),
('Model fees without treating them as market rates',table('Illustrative monthly fee and cost plan',['Line','Assumption','Amount'],[['Recurring invoices','12 × $450','$5,400'],['Cleanup invoices','4 × $250','$1,000'],['Total invoiced','5,400 + 1,000','$6,400'],['External review / contractor payments','Entered monthly cost','−$800'],['Software','Entered monthly cost','−$240'],['Other operating payments','Insurance/admin assumption','−$260'],['Before owner pay and tax','6,400 − 1,300','$5,100']])+p('The $450 and $250 fees are fictional examples, not recommended rates. Define the included work, record cutoff, revision boundary, client responsibilities and separately agreed extras before quoting. A simple fee can conceal excessive cleanup if the source records are incomplete. Client complexity and professional obligations may make the example unsuitable.')+p('Compare delivery economics at the engagement level. If a $450 client takes ten rather than six direct hours, direct revenue per hour changes from $75 to $45 before review and overhead. The correct response might be better intake, a revised scope or a different fee, supported by the actual record rather than an automatic increase.')),
('Separate invoices, receivables and owner withdrawals',p('Opening receivables are $1,800. Invoicing $6,400 and collecting $5,000 leaves $3,200 outstanding: $1,800 + $6,400 − $5,000. The plan assumes no credits or write-offs. A customer payment reduces a receivable; it should not be entered as a second sale.')+p('With $4,500 opening cash, $5,000 collected, $1,300 of operating payments and a $3,200 owner withdrawal, closing cash is $5,000. The owner withdrawal is a separate cash use here, not a wage expense or tax classification. If collections fall to $3,000, closing cash falls to $3,000 even while invoices remain $6,400.')+p('Use a dated <a href="/journal/cash-flow-forecast-template-example/">cash forecast</a> for software renewals, contractor payments and withdrawals. A positive invoiced remainder does not authorize spending against unpaid clients. Keep the planning model separate from the practice’s own accounting and client records.')),
('Add market evidence, intake controls and a review schedule',table('Copyable practice-plan decisions',['Area','Initial plan','Evidence to retain'],[['Buyer','Small service firms with recurring bookkeeping needs','Interviews and qualified inquiries'],['Alternatives','In-house work, another provider or deferred cleanup','Dated scope and response-time comparison'],['Acquisition','Permission-based referrals and targeted educational content','Qualified conversations, proposals and signed scope'],['Intake','Confirm records, access, cutoff and missing items','Checklist and controlled permissions'],['Quality','Separate preparation and review evidence','Exceptions, review owner and release date']])+p('Do not paste client banking, payroll or identity records into a public planning document. Use appropriately controlled systems, necessary access and a documented retention process. A free worksheet is not a client portal or a security certification.')+p('At the first review, compare actual hours, missing-record delays, external review cost, invoices and cash receipts. At the second, revisit client mix and onboarding limits. The <a href="/tools/business-plan-template/">business-plan template</a> organizes assumptions; the <a href="/journal/client-profitability-analysis/">client-profitability guide</a> helps separate delivery cost from a headline fee. Check exact paid-product features before choosing a broader planning workspace.'))
],[SBA,('Xero: grow your accounting practice','https://www.xero.com/uk/accountant-bookkeeper-guides/grow-your-accounting-practice/')],'/planners/agency-client-profitability-capacity-os/')
add('operations-dashboard-example','Operations Dashboard Example: Backlog, Quality & Capacity','Create an operations dashboard that reconciles demand, completions, cancellations, rework and next-week capacity. Includes a small-workshop example.','Workshop dispatch station with separate job-card trays, quality tools and packaged products',[
('Make one operational decision visible',p('An operations dashboard summarizes an ongoing process: what entered the queue, what left it, whether the output met its promise and what work is now constrained. Choose one process and a consistent reporting cutoff. A list of colorful metrics cannot explain why a backlog changed if the movement counts do not reconcile.')+p('This fictional small workshop tracks unique customer jobs over five working days. It differs from the <a href="/journal/project-management-dashboard/">project dashboard</a>, which measures a finite scope against a baseline, and the <a href="/journal/store-performance-dashboard/">store dashboard</a>, which focuses on merchandise sales and stock.')),
('Reconcile the queue before reporting throughput',table('Illustrative weekly job bridge',['Movement','Jobs','Definition'],[['Opening work in progress','18','Unique jobs open at cutoff'],['New accepted jobs','+72','Accepted into this process'],['Cancellations','−4','Removed before completion'],['Completed jobs','−70','Accepted output, counted once'],['Closing work in progress','16','18 + 72 − 4 − 70']])+p('Rework events remain attached to the original job ID. Sending one item back for correction is not a new customer job. If you count each rework pass as a new arrival and completion, the dashboard can show growing throughput without delivering more customer work.')+p('Record cancelled and reopened items explicitly. If a previously completed job is reopened, define whether it re-enters work in progress and adjust the bridge. The example assumes no reopenings or transfers; a real dashboard needs those movements when they exist.')),
('Pair output with quality and delivery',table('Illustrative performance measures',['Metric','Calculation','Result'],[['Throughput','70 accepted completions ÷ 5 working days','14 jobs/day'],['First-pass acceptance','63 accepted without rework ÷ 70 completed','90%'],['On-time completion','61 within agreed date ÷ 70 completed','87.14%'],['Jobs requiring rework','7 of 70 completed','10%'],['Period operating cost per completion','$2,800 ÷ 70','$40']])+p('All 70 jobs ultimately meet the completion definition; seven required correction first. First-pass acceptance therefore differs from final acceptance. The on-time denominator is completed jobs here. If the process has jobs that were due but remain unfinished, add a separate due-cohort service measure so missed promises do not disappear merely because they were not completed.')+p('The $2,800 period cost comprises 84 logged labor hours at an assumed $22 plus $700 materials and $252 other costs. Rework hours are already inside the 84 hours. Do not add seven more hours without checking the timesheet. The $40 figure is a period allocation, not a full product cost or a price recommendation.')),
('Compare remaining effort with usable capacity',p('For next week, 80 available work hours minus 12 hours of scheduled non-delivery work leaves 68 delivery hours. The 16 open jobs require an estimated 24 hours, while expected new accepted work requires 48. Total demand is 72 hours, creating a four-hour shortfall.')+p('Sixteen open jobs are not automatically 16 hours. Estimate the remaining work by job type and current stage. If one specialist owns most of the 24 hours, test that person’s capacity separately; spare time elsewhere may not be interchangeable. The <a href="/journal/agency-capacity-planning-example/">capacity planning example</a> explains that role constraint.')+p('Do not convert the queue into a guaranteed delivery time using a single average throughput number. Priorities, job mix, blockers and arrivals may change. Show oldest open age, explicit promised dates and remaining effort beside the queue total.')),
('Use a source register and an exception-based review',table('Copyable dashboard field register',['Field','Source / owner','Review action'],[['Accepted arrivals and completions','Job ledger with unique IDs','Reconcile the bridge'],['Due date and completion date','Agreed promise and acceptance evidence','Inspect late due-cohort jobs'],['Quality pass and rework','Quality record linked to the job','Identify repeated causes'],['Remaining effort','Delivery owner estimate','Check role capacity'],['Action and deadline','Named process reviewer','Close the next decision']])+p('Start each review with missing or stale data. Then examine the largest delivery or quality exception, choose a specific action and date it. “Clarify the acceptance checklist for the recurring defect before the next batch” is more useful than “improve quality.” Keep the original period export so a later adjustment is traceable.')+p('<strong>Does this need live software?</strong> Not necessarily. A carefully controlled manual register can support the same definitions. This article does not supply automatic integrations or claim a Nexaly connection to your workshop system. <strong>Which metrics belong at the top?</strong> The ones that change the immediate decision: reconciled queue, due-work exceptions, first-pass result and the next capacity constraint.'))
],[('Geckoboard: operations dashboard examples','https://www.geckoboard.com/dashboard-examples/operations/'),('Tableau Help: dashboards','https://help.tableau.com/current/pro/desktop/en-gb/dashboards.htm')],'/planners/owneros-core/')
add('landscape-business-plan','Landscape Business Plan: Crew Hours, Route Costs & Cash','Write a landscape maintenance business plan with crew-hours, travel, weekly visit capacity, costs and collection timing. Includes a weather-delay scenario.','Landscape crew lead reviewing a clipboard beside a maintenance truck and gardening tools',[
('Choose a service and a route boundary',p('A landscape business plan should specify the services, customer area, crew, equipment, visit capacity, costs and payment timing. This example is recurring landscape maintenance, not landscape architecture, construction or chemical application. Those services can require different skills, obligations and equipment.')+p('The fictional company serves a small local route with two paid crew members. Its initial offer is a clearly bounded maintenance visit. Before advertising, the owner must verify the local service requirements, insurance and any applicable professional permissions with the responsible official sources. This example does not establish those requirements or recommend a wage rate.')),
('Separate crew-clock hours from labor hours',table('Illustrative two-person weekly route',['Use of time','Crew-clock hours','Labor-hours equivalent'],[['Paid availability','40','80'],['Travel','8','16'],['Loading / unloading','4','8'],['Maintenance','2','4'],['Weather reserve','4','8'],['Available on site','22','44']])+p('A crew-clock hour means both people working for one elapsed hour. Two people paid for 40 hours each provide 80 labor hours, not 80 elapsed hours on the route. Adding both measures would double-count capacity.')+p('At an estimated 1.1 crew-clock hours per visit, 22 onsite hours support 20 visits. Validate the estimate with actual property scope, access, travel and cleanup. Keep the four-hour weather reserve unbooked until it is needed; selling those hours in advance removes the buffer. Equipment availability and skills can impose a tighter constraint than total hours.')),
('Build a weekly cost and price test',table('Illustrative weekly maintenance model',['Line','Calculation','Amount'],[['Visit revenue','20 × $85','$1,700'],['Fully loaded crew cost','80 labor hours × assumed $16','−$1,280'],['Fuel','Entered route cost','−$120'],['Consumables','20 × $4','−$80'],['Other period costs','Entered cash-paid amount','−$180'],['Operating remainder','1,700 − 1,660','$40']])+p('The $16 fully loaded hourly cost and $85 visit price are fictional assumptions, not employment guidance or local market rates. Include actual wages, employer costs and applicable obligations in the real estimate. The $180 is a stated period amount; it is not the purchase price of a truck or a complete equipment-replacement reserve.')+p('The listed cost per completed visit is $1,660 ÷ 20 = $83 before owner pay, tax and omitted costs. A price of $85 leaves only $2 per visit under these assumptions. Raising the assumed price to $100 would model a $340 weekly remainder at the same 20 visits, but customer acceptance and demand might change. Test price and scope with evidence instead of treating the arithmetic as a sales forecast.')),
('Model weather and collection timing',p('Opening cash is $3,000. If only 80% of the $1,700 revenue is collected in the week, receipts are $1,360 and $340 remains receivable. Paying all $1,660 of listed costs leaves $2,700. The operating remainder is positive $40 while cash falls $300 because part of the work is uncollected.')+table('Illustrative weather delay after the reserve is exhausted',['Line','Base week','Three visits deferred'],[['Completed visits','20','17'],['Revenue','$1,700','$1,445'],['Crew, fuel and other costs','$1,580','$1,580'],['Consumables','$80','$68'],['Operating remainder','$40','−$203']])+p('The delayed visits are moved, not silently cancelled. Their $255 revenue belongs to the future completion period under this model, while wages and other stated period costs remain. Saved consumables are only $12. The next week must have room for the deferred work; do not promise the same hours to new customers.')+p('Keep a <a href="/journal/cash-flow-forecast-template-example/">dated cash forecast</a> for deposits, payroll, invoices and equipment purchases. Receivables are not bank cash. If a customer disputes scope, the plan also needs a documented acceptance and follow-up process.')),
('Copyable landscape plan and first 90-day decisions',table('Filled plan choices to validate',['Area','Initial choice','Evidence'],[['Customer and area','A compact recurring maintenance route','Address cluster, access and actual timed visits'],['Scope','Written visit inclusions and exclusions','Agreed property checklist'],['Acquisition','Local referrals and a small area-specific offer','Qualified requests and retained customers'],['Delivery','Two-person crew and 20-visit modeled ceiling','Timesheet, vehicle and equipment readiness'],['Cash','Invoice and receipt dates separate','Actual collections and upcoming commitments']])+p('By day 30, replace the 1.1-hour estimate with timed visits and compare travel by route. By day 60, check whether recurring visits leave capacity for delays, repairs and quoting. By day 90, decide whether a denser route, different scope, changed price or reduced booking count improves the real result. Do not add a second crew simply because inquiries increased.')+p('Use the <a href="/tools/business-plan-template/">free business-plan worksheet</a> and <a href="/tools/business-startup-checklist/">startup evidence checklist</a> to record assumptions and decisions. For a broader owner workflow, inspect the current <a href="/planners/small-business-planner-2026-2028/">Small Business Planner details</a>; route optimization or field-service integrations are not implied.'))
],[SBA,('Jobber: landscaping business plan','https://www.getjobber.com/academy/landscaping/landscaping-business-plan/')],'/planners/small-business-planner-2026-2028/')
add('crm-for-solopreneurs','CRM for Solopreneurs: A Simple Pipeline & Follow-Up Workflow','Set up a solopreneur CRM with clear stages, unique contacts, dated next actions and separate bookings, invoices and receipts. Includes a worked pipeline example.','Solo creative professional organizing prospect cards and a follow-up calendar',[
('Start with the next client decision, not a software ranking',p('A CRM for solopreneurs should help one person remember who is interested, what was agreed, what should happen next and when to stop following up. Start with a small pipeline and a consistent review. Choose software only after you know which records, permissions and exports the work requires.')+p('This is a workflow guide, not a claim that one CRM is best for every solo business. A spreadsheet may be sufficient for a small manual process; a dedicated service may be useful for controlled access, reminders or integrations. Verify the current vendor documentation rather than assuming a free plan includes those features.')),
('Use stages with observable entry and exit rules',table('Copyable solo-service pipeline',['Stage','Enter when','Next action / exit'],[['Inquiry','A relevant contact request exists','Record source and check fit'],['Qualified','Need, scope and decision path are understood','Book discovery or decline'],['Discovery','A discussion is agreed','Capture scope and permission to propose'],['Proposal','A scoped offer has been sent','Follow up on an agreed date'],['Decision','Buyer is deciding under stated terms','Record won, lost or deferred'],['Won / lost','Outcome is explicit','Hand off delivery or record the reason']])+p('A contact and an opportunity are different records. One contact can have several projects; one project can involve several people. Give each an ID, link the records and deduplicate new entries. Do not create a second opportunity merely because the same person completed another form.')+p('Record a next-action date and the agreed communication method. “Follow up soon” is not a date. A stage should not imply permission to send repeated messages or subscribe someone to marketing. Keep sensitive details out of the sales notes unless they are necessary and handled appropriately.')),
('Reconcile a fictional pipeline',p('Twenty raw lead records contain four duplicates, leaving 16 unique leads. Three are not a fit, leaving 13 qualified opportunities. Four are won, three lost and six remain open. Those outcomes reconcile to 13; the six open items must not be treated as wins.')+table('Illustrative open-opportunity forecast',['Stage','Count × value','Assumed probability','Weighted amount'],[['Discovery','2 × $1,000','20%','$400'],['Proposal','3 × $1,500','50%','$2,250'],['Decision','1 × $2,000','70%','$1,400'],['Total','6 open opportunities','Assumptions only','$4,050']])+p('The $4,050 weighted pipeline is a scenario, not collected cash, committed revenue or a calibrated probability model. These percentages are invented inputs for the example. Replace them only when you have comparable outcome evidence and still show the full unweighted opportunity values.')+p('Four wins among seven closed opportunities is 57.14%. Four wins among all 13 qualified opportunities is 30.77%, with six still unresolved. Label the denominator and cutoff rather than presenting both as the same final win rate.')),
('Separate sales records from invoices and money',p('The four fictional wins are worth $10,000 in booked work. So far $8,000 has been invoiced, $6,000 collected and $2,000 remains invoiced but unpaid. Another $2,000 is booked but not yet invoiced. Those are different balances; do not call the full $10,000 cash or add receipts to bookings as a new sale.')+p('Keep delivery scope and payment evidence in their appropriate records. The CRM can link a project, invoice reference and planned follow-up without copying an entire financial or customer file into every note. Use the <a href="/journal/client-profitability-analysis/">client-profitability guide</a> after you have actual delivery costs; a large booking is not proof of a profitable engagement.')+p('A useful daily view shows due follow-ups, unanswered scope questions and stalled proposals. At a fixed weekly cutoff, reconcile open opportunities and close obsolete ones with a reason. If four of six open items have overdue actions, fix those decisions before collecting a larger unqualified lead list.')),
('Choose and test a CRM with fictional records',table('Selection checklist',['Need','Test before relying on it'],[['One-person capture','Create a contact and linked opportunity without duplicate work'],['Next actions','Find due and overdue work using the documented date behavior'],['Export and restore','Export a small fictional set and verify what can actually be restored'],['Privacy and access','Check permissions and data handling for the intended records'],['Cost and limits','Verify the current official plan, seat and feature limits'],['Exit route','Retain portable records and confirm attachment/history limitations']])+p('Do not choose by a screenshot or copy a vendor’s old subscription price from a comparison article. Test the exception: a lost deal, duplicate inquiry, delayed payment and a reopened project. If a tool cannot keep those distinctions visible, the workflow may become harder to trust.')+p('NexalyPlanner’s <a href="/planners/owneros-core/">OwnerOS Core</a> is a separate documented business workspace, not a promise of email synchronization, a hosted CRM portal or automatic sending. Keep your current record system until a migration test proves that essential fields and history survive. For a dated experiment, use the <a href="/journal/entrepreneurial-skills-practice-plan/">entrepreneurial skills practice plan</a>.'))
],[('HubSpot: set up object pipelines','https://knowledge.hubspot.com/object-settings/set-up-and-customize-pipelines'),('Salesforce: CRM overview','https://www.salesforce.com/crm/what-is-crm/')],'/planners/owneros-core/')
add('entrepreneurial-skills-practice-plan','Entrepreneurial Skills: A 14-Day Practice Plan With Evidence','Practice entrepreneurial skills through customer interviews, pricing, cash, delivery estimates and small experiments. Use a 14-day plan and evidence-based review.','Entrepreneur practicing a customer interview beside a handmade product prototype',[
('Treat a skill as an observable practice',p('Entrepreneurial skills become useful when they change a decision: understanding a customer, making a clear offer, pricing work, planning cash, delivering within capacity and learning from results. Confidence alone is not evidence. Choose one small business scenario and practice with records you can inspect.')+p('The European Commission’s EntreComp framework is a reference for entrepreneurship competence. The original 14-day schedule below is a practical adaptation for a small operating experiment, not an official certification, psychological assessment or a promise of business success. You can extend the timeline when access or evidence takes longer.')),
('Choose seven skills and a concrete output',table('Original practice checklist',['Skill','Practice task','Evidence'],[['Customer listening','Ask neutral questions about a recent problem','Dated anonymized notes; separate quote from interpretation'],['Offer and communication','Describe one outcome, boundary and next step','A one-paragraph offer another person can restate'],['Pricing arithmetic','List unit and period costs','Reconciled contribution with excluded costs visible'],['Cash planning','Map expected receipt and payment dates','Opening + receipts − payments = closing'],['Delivery planning','Estimate work against available hours','Calendar with buffer and acceptance criteria'],['Experiment design','Change one testable assumption','Hypothesis, observation window and stop rule'],['Review and prioritization','Compare forecast with evidence','Continue, revise or stop decision and owner']])+p('The outputs should remain small enough to finish. A market survey of “everyone” is less useful than five carefully recorded conversations with plausible buyers. Five interviews can reveal questions and objections; they do not prove market-wide demand or produce a statistically representative conversion rate.')),
('A 14-day schedule you can adapt',table('Illustrative two-week schedule',['Days','Work','Check before proceeding'],[['1–2','Choose a customer and write neutral interview questions','No leading promises or invented demand'],['3–4','Hold authorized conversations and summarize patterns','Keep observations distinct from assumptions'],['5–6','Draft an offer and a cost model','State scope, price basis and excluded costs'],['7–8','Make a dated cash and capacity plan','Receipts are not bookings; hours must fit'],['9–10','Run a small bounded test','Use a spending/time ceiling and an explicit stop condition'],['11–12','Compare delivery and feedback with the forecast','Count corrections and exceptions'],['13–14','Choose one next action and preserve the evidence','Do not rewrite the original forecast']])+p('You do not have to launch or take payments to practice. Use fictional records, a prototype or a clearly explained research conversation when appropriate. Obtain the necessary permission before using another person’s information or sharing their words publicly. The worksheet does not grant that permission.')),
('Worked example: a small service offer',p('A fictional designer considers a $240 fixed-scope service. Expected direct software and contractor cost is $40, leaving $200 before owner time and overhead. The initial delivery estimate is four hours; the modeled amount before those other costs is $50 per delivery hour.')+p('A pilot instead takes six hours including revisions, so the same $200 is $33.33 per delivery hour. If 12 delivery hours are available, the original three-project assumption needs 18 hours and is six hours over capacity. At the observed effort, two similar projects use all 12 hours before any delivery buffer.')+p('Now separate cash: if each $240 project collects a 50% deposit, two bookings initially collect $240, not $480. Any supplier payments due before the final receipts need their own dates. The useful learning is a narrower scope, a different estimate or fewer bookings, not simply a larger sales target.')+p('Those amounts are fictional and deliberately small. They demonstrate pricing, capacity and cash distinctions, not a viable market rate or a claim that a pilot result predicts every future project.')),
('Review evidence rather than assigning yourself a success score',p('At the review, record what you expected, what you observed, what remains uncertain and what you will change. For the designer, six actual hours is evidence to investigate the revision boundary. It is not proof that the customer is wrong or that every offer must be repriced immediately.')+p('Use a simple status for each practice output: not attempted, drafted, checked against evidence, or revised after feedback. Avoid a single “entrepreneur score” that hides weaknesses. A clear offer does not compensate for a cash gap, and a good spreadsheet does not validate customer demand.')+p('The <a href="/tools/business-plan-template/">business-plan template</a> keeps the assumptions together. The <a href="/tools/business-startup-checklist/">startup checklist</a> assigns evidence and owners, while the <a href="/journal/crm-for-solopreneurs/">solo CRM workflow</a> organizes follow-ups. For wider priorities, compare the <a href="/planners/small-business-planner-2026-2028/">Small Business Planner</a> with your actual needs. No planner can certify commercial readiness or guarantee an outcome.'))
],[('European Commission: EntreComp framework','https://op.europa.eu/en/publication-detail/-/publication/5e633083-27c8-11e6-914b-01aa75ed71a1'),SBA],'/planners/small-business-planner-2026-2028/')
